// 角色卡导入/解析与表单态纯函数。从 src/CharacterScreen.js 原样外提（无行为变化）。
// 不含 React：只依赖 cardParser 的标签表/ID 工具与 buildSystemPrompt，便于单测。

import {
  buildSystemPrompt,
  ensureUniqueIds,
  REGEX_PLACEMENT_LABELS,
} from './cardParser.js';
import { MEMORY_SUMMARY_PREFIX } from '../memory/memoryConstants.js';

// 导入侧同样不带「记忆总结」条目：旧卡（导出未过滤时代做的）里可能带着别处的会话记忆，
// 直接收下就会变成新卡的角色记忆被注入。导入时剔除，与导出侧同一口径。
export function stripMemorySummaryEntries(worldInfo) {
  return (Array.isArray(worldInfo) ? worldInfo : [])
    .filter(entry => !String((entry && entry.comment) || '').trim().startsWith(MEMORY_SUMMARY_PREFIX));
}

// 「图片里没有角色卡数据」的提示文案只留 key，由消费方（CharacterDetailScreen）t() 翻译。
export const NO_CARD_DATA_MESSAGE_KEY = 'character.detail.importNoCardData';
export const LARGE_IMPORT_BYTES = 2 * 1024 * 1024;
export const MAX_IMPORT_BYTES = 32 * 1024 * 1024;
export const CHARACTER_LIST_COLLAPSE_LIMIT = 10;

// FlatList 在 numColumns>1 时，scrollToIndex 的 index 按「行」计数（内部 getItemCount
// = ceil(项数/列数)）。定位滑块给的是「项」序号，套用前必须折算成行号，否则滑到
// 下半部分（项序号 ≥ 行数）会命中 VirtualizedList 的越界 invariant 直接闪退。
export function gridRowIndex(itemIndex, columns = 1) {
  const cols = Math.max(1, Math.floor(Number(columns) || 1));
  const index = Math.max(0, Math.floor(Number(itemIndex) || 0));
  return Math.floor(index / cols);
}

export function formatImportSize(bytes) {
  const value = Number(bytes);
  if (!Number.isFinite(value) || value <= 0) return '';
  if (value >= 1024 * 1024) return `${(value / (1024 * 1024)).toFixed(1)} MB`;
  return `${Math.max(1, Math.round(value / 1024))} KB`;
}

export function isLargeImport(bytes) {
  return Number(bytes) > LARGE_IMPORT_BYTES;
}

export function getPickedAsset(result) {
  if (!result || result.canceled || result.type === 'cancel') return null;
  if (Array.isArray(result.assets) && result.assets[0]) return result.assets[0];
  if (result.uri) return result;
  return null;
}

export function assetLooksLike(asset, ext, mimes) {
  const mime = String(asset?.mimeType || '').toLowerCase();
  const name = String(asset?.name || asset?.uri || '').toLowerCase();
  return mimes.includes(mime) || name.endsWith(ext);
}

export function isPngBuffer(buffer) {
  return (
    buffer
    && buffer.length >= 8
    && buffer[0] === 0x89
    && buffer[1] === 0x50
    && buffer[2] === 0x4e
    && buffer[3] === 0x47
  );
}

export function splitKeywords(text) {
  return String(text || '')
    .split(/[,，\n]/)
    .map(item => item.trim())
    .filter(Boolean);
}

export function placementText(placement, strings = {}) {
  const scopeFallback = strings.scopeFallback || '范围 {key}';
  return placement
    .map(item => REGEX_PLACEMENT_LABELS[item] || scopeFallback.replace('{key}', item))
    .join('、');
}

export function hasCardContent(card) {
  if (!card) return false;
  if (card.name) return true;
  if (card.systemPrompt) return true;
  if (card.worldInfo?.length) return true;
  if (card.regexScripts?.length) return true;
  if (card.presets?.length) return true;
  const fields = card.fields || {};
  return Boolean(
    fields.description
    || fields.personality
    || fields.scenario
    || fields.firstMes
    || (fields.alternateGreetings && fields.alternateGreetings.length)
    || fields.mesExample
    || fields.creatorNotes
    || fields.postHistoryInstructions
  );
}

export function buildCharacterPatch(card, strings = {}) {
  const fields = card.fields || {};
  return {
    id: `card-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`,
    name: card.name || strings.defaultName || '导入角色',
    systemPrompt: fields.systemPrompt || '',
    systemPromptComposed: card.systemPrompt || '',
    description: fields.description || '',
    personality: fields.personality || '',
    scenario: fields.scenario || '',
    firstMes: fields.firstMes || '',
    alternateGreetings: Array.isArray(fields.alternateGreetings) ? fields.alternateGreetings : [],
    mesExample: fields.mesExample || '',
    creatorNotes: fields.creatorNotes || '',
    postHistoryInstructions: fields.postHistoryInstructions || '',
    tags: Array.isArray(fields.tags) ? fields.tags : [],
    worldInfo: stripMemorySummaryEntries(card.worldInfo),
    regexScripts: Array.isArray(card.regexScripts) ? card.regexScripts : [],
    presets: Array.isArray(card.presets) ? card.presets : [],
    // 透传隐式 AI 标识（与 cardForge/forge.js 一致），否则导入的 AI 生成卡丢失追溯信息。
    aigcMeta: card.aigcMeta && typeof card.aigcMeta === 'object' ? card.aigcMeta : null,
    voiceDisplay: ['text', 'voice-text', 'voice'].includes(card.voiceDisplay)
      ? card.voiceDisplay
      : 'text',
    cardExtensions: card.extensions && typeof card.extensions === 'object' && !Array.isArray(card.extensions)
      ? card.extensions
      : {},
    cardExtra: card.extra && typeof card.extra === 'object' && !Array.isArray(card.extra)
      ? card.extra
      : {},
  };
}


export function buildCharacterFormState(character) {
  const source = character && typeof character === 'object' ? character : {};
  return {
    name: String(source.name || ''),
    tags: Array.isArray(source.tags) ? source.tags : [],
    systemPrompt: String(source.systemPrompt || ''),
    description: String(source.description || ''),
    personality: String(source.personality || ''),
    scenario: String(source.scenario || ''),
    firstMes: String(source.firstMes || ''),
    alternateGreetings: Array.isArray(source.alternateGreetings) ? source.alternateGreetings : [],
    mesExample: String(source.mesExample || ''),
    worldInfo: ensureUniqueIds(Array.isArray(source.worldInfo) ? source.worldInfo : [], 'entry'),
    regexScripts: ensureUniqueIds(Array.isArray(source.regexScripts) ? source.regexScripts : [], 'regex'),
    presets: Array.isArray(source.presets) ? source.presets : [],
    avatarUri: String(source.avatarUri || ''),
    bgUri: String(source.bgUri || ''),
    voiceDisplay: ['text', 'voice-text', 'voice'].includes(source.voiceDisplay)
      ? source.voiceDisplay
      : 'text',
  };
}

export function characterFormSignature(character) {
  return JSON.stringify(buildCharacterFormState(character));
}

export function characterWithFormState(character, form) {
  const source = character && typeof character === 'object' ? character : {};
  const state = form || buildCharacterFormState(source);
  return {
    ...source,
    ...state,
    systemPromptComposed: buildSystemPrompt({
      description: state.description,
      personality: state.personality,
      scenario: state.scenario,
      systemPrompt: state.systemPrompt,
      postHistoryInstructions: source.postHistoryInstructions,
    }),
  };
}

export function worldEntryMeta(entry, strings = {}) {
  if (entry.constant) return strings.constant || '常驻';
  const keys = Array.isArray(entry.keys) ? entry.keys.filter(Boolean) : [];
  if (keys.length) return (strings.keywords || '关键词：{keys}').replace('{keys}', keys.join('、'));
  const content = String(entry.content || '').replace(/\s+/g, ' ').trim();
  return content ? content.slice(0, 40) : strings.noKeys || '未设置关键词';
}

// 角色发表情包：解析助手回复里的 `[[表情包:名称]]` 指令。
//
// 设计约束：
// - 只依赖纯文本处理，便于单测与在纯 Node 环境运行；
// - 名称必须命中白名单（用户实际拥有的表情包），模型自造的名称一律丢弃；
// - 标记从正文中剥离，文字与表情包分别成条展示。

const STICKER_DIRECTIVE_PATTERN = /\[\[\s*表情包\s*[:：]\s*([^\]\n]+?)\s*\]\]/g;

function cleanName(value) {
  return String(value === null || value === undefined ? '' : value).trim();
}

// 可用名称清单：去重、trim、过滤空串，保持输入顺序。
export function resolveStickerNames(stickers) {
  const names = [];
  const seen = new Set();
  (Array.isArray(stickers) ? stickers : []).forEach(sticker => {
    const name = cleanName(sticker && sticker.name);
    if (!name || seen.has(name)) return;
    seen.add(name);
    names.push(name);
  });
  return names;
}

// 解析助手回复：返回剥离标记后的正文，以及命中的（白名单内）表情包名称数组。
// 白名单为空时不做任何解析，原样返回（避免无表情包时误伤正文）。
export function extractStickerDirectives(text, names) {
  const source = String(text === null || text === undefined ? '' : text);
  const allowed = new Set(
    (Array.isArray(names) ? names : []).map(cleanName).filter(Boolean)
  );
  if (allowed.size === 0) return { text: source, stickers: [] };

  const stickers = [];
  const stripped = source.replace(STICKER_DIRECTIVE_PATTERN, (match, rawName) => {
    const name = cleanName(rawName);
    if (!allowed.has(name)) return match;
    stickers.push(name);
    return '';
  });

  // 只有真正剥离了指令才做空白收敛：否则（用户有表情包但本条回复没用到）
  // 会把正常 Markdown 的缩进、空行、行尾双空格一并改坏。
  if (stickers.length === 0) return { text: source, stickers };
  return {
    text: normalizeDirectiveWhitespace(stripped),
    stickers,
  };
}

// 剥离指令后可能留下成片空行，仅收敛多余空行。刻意不动行尾空格（Markdown 硬换行）
// 与整体缩进：同一条回复里既有指令又有正常 Markdown 时，不能连带改坏正文。
function normalizeDirectiveWhitespace(text) {
  return String(text || '').replace(/\n{3,}/g, '\n\n');
}

// 表情包教学提示（模型可见的提示词，刻意不进 i18n；开关开启且有表情包时注入系统提示）。
// 措辞可改。清单为空时返回空串——调用方据此不注入（无表情包就不该发指令）。
const STICKER_INSTRUCTION_TEMPLATE = [
  '你可以在情绪合适时用表情包回应。想发表情包时，在回复里单独写一行：[[表情包:名称]]，',
  '名称必须严格从下列清单中选择：{names}。',
  '不要自造、改写或翻译名称；也不要在每条回复里都发表情包，只在情绪真正贴合时偶尔使用。',
].join('\n');

export function buildStickerInstruction(names) {
  const list = (Array.isArray(names) ? names : []).map(cleanName).filter(Boolean);
  if (list.length === 0) return '';
  // 用替换函数而非替换字符串：表情包名可含 `$&`/`$1` 等模式，作为替换字符串会被解释成注入。
  return STICKER_INSTRUCTION_TEMPLATE.replace('{names}', () => list.join('、'));
}

import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';

import {
  DEFAULT_CHARACTER,
  DEFAULT_ASSISTANT_LEGACY_PROMPTS,
  getActiveCharacterId,
  getCharacterLibrary,
  isCharacterLibraryWriteBlocked,
  saveCharacterLibrary,
  setActiveCharacterId,
  sortCharacters,
} from '../storage/characters.js';
import { saveCharacterState } from '../storage/characterState.js';
import {
  getSessions,
  getActiveSessionId,
  whenSessionMutationsSettled,
  setActiveSessionId,
  setSessionPinned,
  startNewSession,
  appendProactiveMessage,
  cloneSession as cloneSessionStorage,
  deleteSession as deleteSessionStorage,
  deleteSessions as deleteSessionsStorage,
  reconcileVectorIndexes,
  reconcileWorldMemories,
} from '../storage/sessions.js';
import { getProactiveSettings, bindProactiveSlotSession } from '../storage/moments.js';
import { collectOrphanImageFiles } from '../storage/orphanMedia.js';

import {
  describeDefaultArtwork,
  describeDefaultAssistantRefresh,
  resolveActiveId,
  runWithRollback,
  withAddedCharacter,
  withDeletedCharacter,
  withDeletedCharacters,
  withPinnedCharacter,
  withSwitchedCharacter,
  withUpdatedCharacter,
} from './characterLibrary.js';
import { resolveActiveSessionId, sortSessions } from './sessionLibrary.js';
// 不变量错误的文案走 i18n：这些错误会经 UI 的 catch 弹给用户（CharacterDetailScreen 等
// 会把 error.message 直接显示），硬编码中文时英文用户看到中文。
import { tActive } from '../i18n/index.js';
import { materializeDefaultArtwork } from '../character/defaultCharacterAssets.js';
import { ingestProactiveMessagesInto } from './proactiveIngest.js';
// 状态守卫文案走 tActive（同步取词）：这些 throw 的 message 会被调用方 catch 后
// 经 error.message 直通 Alert/提示条，硬编码中文会让英文界面弹中文。
// 用 tActive 而不是 hook：throw 发生在 async 回调/事件处理里，拿不到 React 上下文。
import { tActive } from '../i18n/index.js';

const AppContext = createContext(null);

export function AppProvider({ children }) {
  const [characters, setCharactersState] = useState([DEFAULT_CHARACTER]);
  const [activeId, setActiveIdState] = useState(DEFAULT_CHARACTER.id);
  const [sessions, setSessionsState] = useState([]);
  const [activeSessionId, setActiveSessionIdState] = useState('');
  const [pendingTarget, setPendingTargetState] = useState(null);
  // 听歌等面板「接话」带入的引用：{ sessionId, payload }。与 pendingTarget 同一
  // ref+state 惯例——目标会话激活后由聊天页消费一次，消费前多次设置以最后一次为准。
  const [pendingQuote, setPendingQuoteState] = useState(null);
  const [loaded, setLoaded] = useState(false);
  // 主动消息落库后自增，通知聊天页重新读取当前会话消息（同会话追加时 activeSessionId 不变）。
  const [messageRefreshTick, setMessageRefreshTick] = useState(0);
  const charactersRef = useRef([DEFAULT_CHARACTER]);
  const activeIdRef = useRef(DEFAULT_CHARACTER.id);
  const sessionsRef = useRef([]);
  const activeSessionIdRef = useRef('');
  const pendingTargetRef = useRef(null);
  const pendingQuoteRef = useRef(null);
  const loadedRef = useRef(false);
  const mutationRef = useRef(Promise.resolve());

  const enqueueMutation = useCallback(operation => {
    const pending = mutationRef.current.then(operation);
    mutationRef.current = pending.catch(() => {});
    return pending;
  }, []);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        // 记忆归属对账必须在读角色库**之前**：它会退休卡上不合法的「记忆总结」条目
        // （单会话时代残留的、删会话后留下的、跨卡流通过来的），若先读进内存，
        // 内存快照就会与盘不一致——用户随后编辑角色时会把退休标记又覆盖回去。
        // 代价很小：只有卡上真有生效的记忆条目时才会去读会话消息。
        await reconcileWorldMemories().catch(error => {
          if (__DEV__) console.warn('[memory] world memory reconciliation failed', error);
        });
        const [list, storedActiveId, sessionList, storedActiveSessionId] = await Promise.all([
          getCharacterLibrary(),
          getActiveCharacterId(),
          getSessions(),
          getActiveSessionId(),
        ]);
        if (cancelled) return;
        const libraryBlocked = isCharacterLibraryWriteBlocked();
        // 默认角色（EasyChat2 助手）首次运行时补上内置头像/背景：仅当用户尚未自定义。
        // 落盘为 avatars/ 下的普通文件，使所有既有渲染点无需改动即可生效。
        let resolvedList = list;
        if (!libraryBlocked) {
          const defaultCharacter = list.find(item => item.id === DEFAULT_CHARACTER.id);
          const needs = describeDefaultArtwork({
            id: DEFAULT_CHARACTER.id,
            avatarUri: defaultCharacter && defaultCharacter.avatarUri,
            bgUri: defaultCharacter && defaultCharacter.bgUri,
            defaultId: DEFAULT_CHARACTER.id,
          });
          if (needs.avatar || needs.bg) {
            const artwork = await materializeDefaultArtwork();
            if (cancelled) return;
            if (artwork.avatarUri || artwork.bgUri) {
              resolvedList = list.map(item => {
                if (item.id !== DEFAULT_CHARACTER.id) return item;
                return {
                  ...item,
                  avatarUri: needs.avatar && artwork.avatarUri ? artwork.avatarUri : item.avatarUri,
                  bgUri: needs.bg && artwork.bgUri ? artwork.bgUri : item.bgUri,
                };
              });
              await saveCharacterLibrary(resolvedList).catch(() => {});
            }
          }
          // 内置助手：系统提示仍是历史内置文案时刷新为最新版（用户改过的不动，非内置卡不动）。
          const assistantRefresh = describeDefaultAssistantRefresh({
            id: DEFAULT_CHARACTER.id,
            builtin: defaultCharacter && defaultCharacter.builtin,
            systemPrompt: defaultCharacter && defaultCharacter.systemPrompt,
            defaultId: DEFAULT_CHARACTER.id,
            legacyPrompts: DEFAULT_ASSISTANT_LEGACY_PROMPTS,
            nextPrompt: DEFAULT_CHARACTER.systemPrompt,
          });
          if (assistantRefresh) {
            resolvedList = resolvedList.map(item => (
              item.id === DEFAULT_CHARACTER.id ? { ...item, ...assistantRefresh } : item
            ));
            await saveCharacterLibrary(resolvedList).catch(() => {});
          }
        }
        const resolved = resolveActiveId(resolvedList, storedActiveId);
        const sortedSessions = sortSessions(sessionList);
        const resolvedSessionId = resolveActiveSessionId(sortedSessions, storedActiveSessionId);
        charactersRef.current = resolvedList;
        activeIdRef.current = libraryBlocked ? (storedActiveId || resolved) : resolved;
        sessionsRef.current = sortedSessions;
        activeSessionIdRef.current = resolvedSessionId;
        setCharactersState(resolvedList);
        setActiveIdState(libraryBlocked ? (storedActiveId || resolved) : resolved);
        setSessionsState(sortedSessions);
        setActiveSessionIdState(resolvedSessionId);
        if (!libraryBlocked && resolved !== storedActiveId) {
          setActiveCharacterId(resolved).catch(() => {});
        }
        if (resolvedSessionId !== storedActiveSessionId && resolvedSessionId) {
          setActiveSessionId(resolvedSessionId).catch(() => {});
        }
      } catch (error) {
        if (cancelled) return;
        charactersRef.current = [DEFAULT_CHARACTER];
        activeIdRef.current = DEFAULT_CHARACTER.id;
        sessionsRef.current = [];
        activeSessionIdRef.current = '';
        setCharactersState([DEFAULT_CHARACTER]);
        setActiveIdState(DEFAULT_CHARACTER.id);
        setSessionsState([]);
        setActiveSessionIdState('');
      } finally {
        if (!cancelled) {
          loadedRef.current = true;
          setLoaded(true);
          reconcileVectorIndexes().catch(error => {
            if (__DEV__) console.warn('[vector] startup reconciliation failed', error);
          });
          collectOrphanImageFiles().catch(() => {});
        }
      }
    };
    load();
    return () => {
      cancelled = true;
    };
  }, []);

  const applyList = useCallback(list => {
    const sorted = sortCharacters(list);
    charactersRef.current = sorted;
    setCharactersState(sorted);
    return sorted;
  }, []);

  // 从盘上重读角色库并覆盖内存。存储层可能在本轮操作里改过角色卡（删除会话触发的
  // 记忆归属对账会退休卡上的记忆条目）——内存快照不跟上，用户下次编辑角色时就会把
  // 退休标记整表覆盖回去。
  const refreshCharactersDirect = useCallback(async () => {
    const list = await getCharacterLibrary();
    return applyList(list);
  }, [applyList]);

  // 排队版本：给外部（记忆体检弹层的清理动作等）用，避免与角色更新并发读写打架。
  const refreshCharacters = useCallback(
    () => enqueueMutation(() => refreshCharactersDirect()),
    [enqueueMutation, refreshCharactersDirect]
  );

  const restore = useCallback(snapshot => {
    charactersRef.current = snapshot.list;
    activeIdRef.current = snapshot.activeId;
    setCharactersState(snapshot.list);
    setActiveIdState(snapshot.activeId);
  }, []);

  const snapshotState = useCallback(() => ({
    list: charactersRef.current,
    activeId: activeIdRef.current,
  }), []);

  const updateCharacter = useCallback(async patch => {
    if (!loadedRef.current) {
      throw new Error(tActive('error.context.characterNotLoaded'));
    }
    const targetId = patch?.id || activeIdRef.current;
    return enqueueMutation(async () => {
      const snapshot = snapshotState();
      if (!snapshot.list.some(item => item.id === targetId)) {
        throw new Error(tActive('error.context.characterNotFound'));
      }
      const { list, character } = withUpdatedCharacter(snapshot.list, targetId, patch);
      applyList(list);
      await runWithRollback(snapshot, restore, () => saveCharacterLibrary(list));
      return character;
    });
  }, [applyList, restore, snapshotState, enqueueMutation]);

  const switchCharacter = useCallback(async id => {
    if (!loadedRef.current) {
      throw new Error(tActive('error.context.characterNotLoaded'));
    }
    return enqueueMutation(async () => {
      const snapshot = snapshotState();
      const { list, character, found } = withSwitchedCharacter(
        snapshot.list,
        id,
        Date.now()
      );
      if (!found) {
        throw new Error(tActive('error.context.characterNotFound'));
      }
      if (id === snapshot.activeId) return character;
      applyList(list);
      activeIdRef.current = id;
      setActiveIdState(id);
      await runWithRollback(snapshot, restore, () => saveCharacterState(list, id));
      return character;
    });
  }, [applyList, restore, snapshotState, enqueueMutation]);

  const addCharacter = useCallback(async character => {
    if (!loadedRef.current) {
      throw new Error(tActive('error.context.characterNotLoaded'));
    }
    return enqueueMutation(async () => {
      const snapshot = snapshotState();
      const created = withAddedCharacter(snapshot.list, character, Date.now());
      applyList(created.list);
      activeIdRef.current = created.character.id;
      setActiveIdState(created.character.id);
      await runWithRollback(snapshot, restore, () =>
        saveCharacterState(created.list, created.character.id)
      );
      return created.character;
    });
  }, [applyList, restore, snapshotState, enqueueMutation]);

  const deleteCharacter = useCallback(async (id, options = {}) => {
    if (!loadedRef.current) {
      throw new Error(tActive('error.context.characterNotLoaded'));
    }
    if (id === DEFAULT_CHARACTER.id) {
      throw new Error(tActive('error.context.defaultCharacterUndeletable'));
    }
    return enqueueMutation(async () => {
      const snapshot = snapshotState();
      const result = withDeletedCharacter(snapshot.list, id, snapshot.activeId);
      if (!result.removed) {
        throw new Error(tActive('error.context.characterNotFound'));
      }
      applyList(result.list);
      activeIdRef.current = result.activeId;
      setActiveIdState(result.activeId);
      await runWithRollback(snapshot, restore, () =>
        saveCharacterState(
          result.list,
          result.activeId,
          id,
          options.clearVectorIds || []
        )
      );
      return result.list;
    });
  }, [applyList, restore, snapshotState, enqueueMutation]);

  const pinCharacter = useCallback(async (id, pinned) => {
    if (!loadedRef.current) {
      throw new Error(tActive('error.context.characterNotLoaded'));
    }
    return enqueueMutation(async () => {
      const snapshot = snapshotState();
      const result = withPinnedCharacter(snapshot.list, id, pinned);
      if (!result.found) {
        throw new Error(tActive('error.context.characterNotFound'));
      }
      applyList(result.list);
      await runWithRollback(snapshot, restore, () =>
        saveCharacterState(result.list, snapshot.activeId)
      );
      return result.character;
    });
  }, [applyList, restore, snapshotState, enqueueMutation]);

  const deleteCharacters = useCallback(async (ids, options = {}) => {
    if (!loadedRef.current) {
      throw new Error(tActive('error.context.characterNotLoaded'));
    }
    const list = (Array.isArray(ids) ? ids : []).map(String)
      .filter(id => id && id !== DEFAULT_CHARACTER.id);
    if (list.length === 0) {
      throw new Error(tActive('error.context.noDeletableCharacters'));
    }
    return enqueueMutation(async () => {
      const snapshot = snapshotState();
      // 默认角色不可删，删掉其余全部角色后仍会保留默认角色，因此这里不再拦截“全选删除”。
      const result = withDeletedCharacters(snapshot.list, list, snapshot.activeId);
      if (result.removedCount === 0) {
        throw new Error(tActive('error.context.characterNotFound'));
      }
      applyList(result.list);
      activeIdRef.current = result.activeId;
      setActiveIdState(result.activeId);
      await runWithRollback(snapshot, restore, () =>
        saveCharacterState(
          result.list,
          result.activeId,
          list,
          options.clearVectorIds || []
        )
      );
      return result.list;
    });
  }, [applyList, restore, snapshotState, enqueueMutation]);

  const applySessions = useCallback(list => {
    const sorted = sortSessions(list);
    sessionsRef.current = sorted;
    setSessionsState(sorted);
    return sorted;
  }, []);

  const restoreSessions = useCallback(snapshot => {
    sessionsRef.current = snapshot.sessions;
    activeSessionIdRef.current = snapshot.activeSessionId;
    setSessionsState(snapshot.sessions);
    setActiveSessionIdState(snapshot.activeSessionId);
  }, []);

  const snapshotSessions = useCallback(() => ({
    sessions: sessionsRef.current,
    activeSessionId: activeSessionIdRef.current,
  }), []);

  const applyActiveSessionId = useCallback(id => {
    activeSessionIdRef.current = id;
    setActiveSessionIdState(id);
  }, []);

  const setPendingTarget = useCallback(target => {
    const value = target && target.sessionId && target.messageId
      ? { sessionId: String(target.sessionId), messageId: String(target.messageId) }
      : null;
    pendingTargetRef.current = value;
    setPendingTargetState(value);
  }, []);

  const consumePendingTarget = useCallback(() => {
    const value = pendingTargetRef.current;
    pendingTargetRef.current = null;
    setPendingTargetState(null);
    return value;
  }, []);

  // payload 形状与 buildQuotePayload 一致（{ id, name, role, text }）；id 允许为空
  // ——评论不是会话内消息，点引用块不定位（onPressQuoteBlock 对空 id 直接返回）。
  const setPendingQuote = useCallback(quote => {
    const value = quote && quote.sessionId && quote.payload
      ? {
        sessionId: String(quote.sessionId),
        payload: {
          id: String((quote.payload && quote.payload.id) || ''),
          name: String((quote.payload && quote.payload.name) || '').trim(),
          role: String((quote.payload && quote.payload.role) || 'assistant'),
          text: String((quote.payload && quote.payload.text) || '').trim(),
        },
      }
      : null;
    if (value && !value.payload.text) return;
    pendingQuoteRef.current = value;
    setPendingQuoteState(value);
  }, []);

  const consumePendingQuote = useCallback(() => {
    const value = pendingQuoteRef.current;
    pendingQuoteRef.current = null;
    setPendingQuoteState(null);
    return value;
  }, []);

  const refreshSessionsDirect = useCallback(async () => {
    // 先等存储层会话写入（含旧消息迁移）排空：迁移在 storage 的队列里，
    // 与这里的 mutation 队列不是同一个；不等待会在迁移写盘中途读到中间态。
    await whenSessionMutationsSettled();
    const [sessionList, storedActiveSessionId] = await Promise.all([
      getSessions(),
      getActiveSessionId(),
    ]);
    const sorted = applySessions(sessionList);
    const resolved = resolveActiveSessionId(sorted, storedActiveSessionId);
    applyActiveSessionId(resolved);
    return sorted;
  }, [applySessions, applyActiveSessionId]);

  // 外部刷新也要进 mutation 队列：否则迁移/写入进行中的刷新可能用旧快照覆盖新 Context。
  const refreshSessions = useCallback(
    () => enqueueMutation(() => refreshSessionsDirect()),
    [enqueueMutation, refreshSessionsDirect]
  );

  const refreshAppData = useCallback(async () => {
    await enqueueMutation(async () => {
      const [list, storedActiveId, sessionList, storedActiveSessionId] = await Promise.all([
        getCharacterLibrary(),
        getActiveCharacterId(),
        getSessions(),
        getActiveSessionId(),
      ]);
      const resolvedList = Array.isArray(list) && list.length > 0 ? list : [DEFAULT_CHARACTER];
      const resolved = resolveActiveId(resolvedList, storedActiveId);
      const sortedSessions = sortSessions(sessionList);
      const resolvedSessionId = resolveActiveSessionId(sortedSessions, storedActiveSessionId);
      charactersRef.current = resolvedList;
      activeIdRef.current = resolved;
      sessionsRef.current = sortedSessions;
      activeSessionIdRef.current = resolvedSessionId;
      setCharactersState(resolvedList);
      setActiveIdState(resolved);
      setSessionsState(sortedSessions);
      setActiveSessionIdState(resolvedSessionId);
      setMessageRefreshTick(tick => tick + 1);
    });
  }, [enqueueMutation]);

  const ensureCharacterSession = useCallback(async (characterId, opening = null) => {
    if (!loadedRef.current) {
      throw new Error(tActive('error.context.sessionNotLoaded'));
    }
    return enqueueMutation(async () => {
      const targetId = String(characterId || '');
      const existing = sessionsRef.current.find(session => session.characterId === targetId);
      if (existing) {
        if (activeSessionIdRef.current !== existing.id) {
          applyActiveSessionId(existing.id);
          await setActiveSessionId(existing.id);
        }
        return existing;
      }
      try {
        const created = await startNewSession(targetId, opening);
        await refreshSessionsDirect();
        return sessionsRef.current.find(session => session.id === created.id) || created;
      } catch (error) {
        await refreshSessionsDirect().catch(() => {});
        throw error;
      }
    });
  }, [applyActiveSessionId, refreshSessionsDirect, enqueueMutation]);

  // 主动消息落库：把原生待写队列里的消息逐条写入各自角色的单聊会话，再刷新列表。
  // 目标会话由槽的 sessionTargetId 决定：命中该角色的历史对话则写入，否则新建一段并把槽绑定过去
  // （下次触发即固定复用；该会话若被删除则视为空，再次新建）。
  // 返回 { written, skipped, deferred, targetSessions }：
  //   written        已写入，可 ack 删除；
  //   skipped        结构残缺、永远无法处理，可 ack 删除；
  //   deferred       暂时处理不了（角色不在库/写入失败），**不 ack**，保留重试；
  //   targetSessions roleId → 本次消息实际写入的 sessionId，供通知跳转精确切到那段会话。
  // Z 系采纳 #9：领域逻辑外提到 context/proactiveIngest.js（可单测），这里只做装配。
  const ingestProactiveMessages = useCallback(async messages => {
    if (!loadedRef.current) {
      return { written: [], skipped: [], deferred: [], targetSessions: {} };
    }
    return ingestProactiveMessagesInto({
      messages,
      characters: charactersRef.current,
      getProactiveSettings,
      appendProactiveMessage,
      bindProactiveSlotSession,
      onWritten: async () => {
        await refreshSessionsDirect().catch(() => {});
        setMessageRefreshTick(tick => tick + 1);
      },
    });
  }, [refreshSessionsDirect]);

  const switchSession = useCallback(async id => {
    if (!loadedRef.current) {
      throw new Error(tActive('error.context.sessionNotLoaded'));
    }
    return enqueueMutation(async () => {
      const snapshot = snapshotSessions();
      const target = snapshot.sessions.find(session => session.id === id);
      if (!target) {
        throw new Error(tActive('error.context.sessionNotFound'));
      }
      if (id === snapshot.activeSessionId) return target;
      applyActiveSessionId(id);
      await runWithRollback(snapshot, restoreSessions, () => setActiveSessionId(id));
      return target;
    });
  }, [applyActiveSessionId, restoreSessions, snapshotSessions, enqueueMutation]);

  const pinSession = useCallback(async id => {
    if (!loadedRef.current) {
      throw new Error(tActive('error.context.sessionNotLoaded'));
    }
    return enqueueMutation(async () => {
      const snapshot = snapshotSessions();
      if (!snapshot.sessions.some(session => session.id === id)) {
        throw new Error(tActive('error.context.sessionNotFound'));
      }
      try {
        // 交给存储层在会话队列内读-改-写：用内存旧快照整表覆盖会打回并发写入
        // （如主动消息落库新建的会话行）。
        const updated = await setSessionPinned(id, !(snapshot.sessions.find(
          session => session.id === id
        ) || {}).pinned);
        const next = snapshot.sessions.map(session => (
          session.id === id ? (updated || session) : session
        ));
        return applySessions(next);
      } catch (error) {
        await refreshSessionsDirect().catch(() => {});
        throw error;
      }
    });
  }, [applySessions, refreshSessionsDirect, snapshotSessions, enqueueMutation]);

  const cloneSession = useCallback(async id => {
    if (!loadedRef.current) {
      throw new Error(tActive('error.context.sessionNotLoaded'));
    }
    return enqueueMutation(async () => {
      const snapshot = snapshotSessions();
      if (!snapshot.sessions.some(session => session.id === id)) {
        throw new Error(tActive('error.context.sessionNotFound'));
      }
      const copy = await cloneSessionStorage(id);
      applySessions([...sessionsRef.current, copy]);
      return copy;
    });
  }, [applySessions, snapshotSessions, enqueueMutation]);

  const deleteSession = useCallback(async id => {
    if (!loadedRef.current) {
      throw new Error(tActive('error.context.sessionNotLoaded'));
    }
    return enqueueMutation(async () => {
      try {
        const result = await deleteSessionStorage(id);
        applySessions(result.sessions);
        applyActiveSessionId(result.activeSessionId);
        // 删除会话会触发记忆归属对账（可能退休卡上的记忆条目），内存角色库要跟盘一致。
        await refreshCharactersDirect().catch(() => {});
        return result;
      } catch (error) {
        await refreshSessionsDirect().catch(() => {});
        throw error;
      }
    });
  }, [applySessions, applyActiveSessionId, refreshCharactersDirect, refreshSessionsDirect, enqueueMutation]);

  const deleteSessions = useCallback(async (ids, excludedCharacterIds = []) => {
    if (!loadedRef.current) {
      throw new Error(tActive('error.context.sessionNotLoaded'));
    }
    const targets = (Array.isArray(ids) ? ids : [])
      .map(id => String(id || ''))
      .filter(Boolean);
    const excluded = new Set(
      (Array.isArray(excludedCharacterIds) ? excludedCharacterIds : [])
        .map(id => String(id || ''))
        .filter(Boolean)
    );
    if (targets.length === 0) return sessionsRef.current;
    return enqueueMutation(async () => {
      const snapshot = snapshotSessions();
      try {
        const result = await deleteSessionsStorage(targets);
        let sorted = applySessions(result.sessions);
        let resolved = resolveActiveSessionId(sorted, result.activeSessionId);
        if (targets.includes(snapshot.activeSessionId) && sorted.length === 0) {
          const current = snapshot.sessions.find(
            session => session.id === snapshot.activeSessionId
          );
          const available = charactersRef.current.filter(item => !excluded.has(String(item.id || '')));
          const currentOwner = current && current.type !== 'group'
            ? String(current.characterId || '')
            : '';
          const activeOwner = String(activeIdRef.current || '');
          const fallbackCharacterId = (
            (currentOwner && available.some(item => item.id === currentOwner) && currentOwner)
            || (available.some(item => item.id === activeOwner) && activeOwner)
            || (available.find(item => item.id === DEFAULT_CHARACTER.id) || {}).id
            || (available[0] || {}).id
            || ''
          );
          await startNewSession(fallbackCharacterId);
          sorted = await refreshSessionsDirect();
          resolved = resolveActiveSessionId(sorted, activeSessionIdRef.current);
        }
        applyActiveSessionId(resolved);
        // 同上：批量删除后把角色库的内存快照刷新回与盘一致。
        await refreshCharactersDirect().catch(() => {});
        return sorted;
      } catch (error) {
        await refreshSessionsDirect().catch(() => {});
        throw error;
      }
    });
  }, [applySessions, applyActiveSessionId, refreshCharactersDirect, refreshSessionsDirect, enqueueMutation]);

  // activeId 失效（存储损坏 / 角色被外部删除）时界面角色会退回初始卡。若同时继续对外
  // 暴露失效的 activeId，就会造成“高亮的角色”和“当前角色”不是同一个的身份错位，后续
  // 按 activeId 落盘的数据也会指错人。这里统一以解析出的角色为准：character.id 就是
  // 唯一有效的 activeId。
  const character = useMemo(
    () => characters.find(item => item.id === activeId)
      || characters.find(item => item.id === DEFAULT_CHARACTER.id)
      || DEFAULT_CHARACTER,
    [characters, activeId]
  );
  const resolvedActiveId = character.id;

  // activeId 与当前角色不一致时立即修正并落盘，避免失效 id 一直留在存储里。
  useEffect(() => {
    if (!loaded || isCharacterLibraryWriteBlocked()) return;
    if (activeIdRef.current === resolvedActiveId) return;
    activeIdRef.current = resolvedActiveId;
    setActiveIdState(resolvedActiveId);
    setActiveCharacterId(resolvedActiveId).catch(() => {});
  }, [loaded, resolvedActiveId]);

  const value = useMemo(
    () => ({
      character,
      characters,
      activeId: resolvedActiveId,
      loaded,
      updateCharacter,
      switchCharacter,
      addCharacter,
      deleteCharacter,
      pinCharacter,
      deleteCharacters,
      sessions,
      activeSessionId,
      switchSession,
      pinSession,
      cloneSession,
      deleteSession,
      deleteSessions,
      refreshSessions,
      refreshCharacters,
      refreshAppData,
      ensureCharacterSession,
      ingestProactiveMessages,
      messageRefreshTick,
      pendingTarget,
      setPendingTarget,
      consumePendingTarget,
      pendingQuote,
      setPendingQuote,
      consumePendingQuote,
    }),
    [
      character,
      characters,
      resolvedActiveId,
      loaded,
      updateCharacter,
      switchCharacter,
      addCharacter,
      deleteCharacter,
      pinCharacter,
      deleteCharacters,
      sessions,
      activeSessionId,
      switchSession,
      pinSession,
      cloneSession,
      deleteSession,
      deleteSessions,
      refreshSessions,
      refreshCharacters,
      refreshAppData,
      ensureCharacterSession,
      ingestProactiveMessages,
      messageRefreshTick,
      pendingTarget,
      setPendingTarget,
      consumePendingTarget,
      pendingQuote,
      setPendingQuote,
      consumePendingQuote,
    ]
  );

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
}

export function useApp() {
  const ctx = useContext(AppContext);
  if (!ctx) {
    // 开发者错误（在 Provider 外用 hook），但仍走 i18n：仓库铁律是用户可见文案不硬编码，
    // 且开发期报错也可能被错误边界渲染到界面上。
    throw new Error(tActive('error.context.providerMissing'));
  }
  return ctx;
}

// 分级日志（Z 系采纳 #10，对照 zai-org/ZCode 的 createServiceLogger）。
//
// 现状：全仓 30+ 处 `console.warn/error`，多数裹在 `if (__DEV__)` 里，生产环境
// 既不落盘、也没有统一口径（有的写 storage，有的写 unhandled，有的纯 console）。
// 这里定一条统一的纪律：
//   debug  协议原始数据、流式 chunk 等高频诊断——**只在 dev**，不落盘、不刷屏；
//   info   生命周期、一次性初始化等生产可用事件；
//   warn   可恢复异常（失败但已兜底）；
//   error  崩溃、握手失败、鉴权丢失等不可恢复错误。
// 所有文本经 redact 脱敏；落盘由注入的 sink 决定（默认接本地诊断日志）。
// redact 不可用时**省略文本**（fail-closed），绝不回落原文——见下方 clean 的注释。
//
// 纯模块：零 import、零原生依赖（redact 由调用方注入），Node 直测。

export const LOG_LEVELS = Object.freeze(['debug', 'info', 'warn', 'error']);
const RANK = Object.freeze({ debug: 10, info: 20, warn: 30, error: 40 });

// 脱敏器不可用时的占位文本：**绝不回落原文**。
// 刻意不走 i18n 且不导出：本模块是零 import 的纯模块（Node 直测、不拖 i18n/原生依赖），
// 该文本只出现在诊断日志里（不是界面文案），而 eslint 的硬编码中文规则只查
// Alert/throw/JSX 正文与**模块级导出**常量——非导出常量不在其内。
const REDACT_UNAVAILABLE_TEXT = '[脱敏不可用，已省略]';

function safeStringify(value) {
  if (value === undefined) return '';
  if (value instanceof Error) return value.message || String(value);
  try {
    return JSON.stringify(value);
  } catch (error) {
    return String(value);
  }
}

export function createLogger({
  scope = 'app',
  minLevel = 'info',
  dev = false,
  sink = null,
  consoleLike = null,
  redact = null,
} = {}) {
  const threshold = Number.isFinite(RANK[minLevel]) ? RANK[minLevel] : RANK.info;
  // 脱敏的降级方向必须是 **fail-closed**（先例 src/localModel/adapter.js:278
  // 「fail-closed：没钥匙也清」）：脱敏器没注入、抛错、或返回非字符串时，
  // 一律**省略文本**并留占位符，绝不回落 `String(text)` 原文。
  //
  // 为什么不能回落原文：redact 由调用方注入（应用装配点是 src/logging/index.js），
  // 它拿不到脱敏器是**异常态**（模块加载失败）。回落原文等于把「脱敏坏了」这件
  // 事悄悄转换成「把明文密钥写进本地诊断日志」——诊断日志的对外承诺是
  // 「全部文本经 maskSecrets 脱敏，绝不落明文密钥」（storage/diagnostics.js:5）。
  // 占位符还会让这条异常在日志里可见，而不是无声无息。
  const clean = text => {
    const raw = String(text);
    if (typeof redact !== 'function') return REDACT_UNAVAILABLE_TEXT;
    try {
      const masked = redact(raw);
      return typeof masked === 'string' ? masked : REDACT_UNAVAILABLE_TEXT;
    } catch (error) {
      return REDACT_UNAVAILABLE_TEXT;
    }
  };

  const log = (level, message, detail) => {
    if (!Number.isFinite(RANK[level]) || RANK[level] < threshold) return;
    // debug 只在 dev 生效：生产既不落盘也不刷屏。
    if (level === 'debug' && !dev) return;
    const text = clean(message === undefined || message === null ? '' : message);
    const detailText = detail === undefined ? '' : safeStringify(detail);
    if (consoleLike && typeof consoleLike[level] === 'function') {
      consoleLike[level](`[${scope}] ${text}${detailText ? ` ${detailText}` : ''}`);
    }
    // 只有 info 及以上落盘；debug 是纯诊断，不进诊断日志。
    if (level !== 'debug' && typeof sink === 'function') {
      try {
        sink({ level, scope, message: text, detail: detail === undefined ? null : detailText, at: Date.now() });
      } catch (error) {
        // 日志自身失败绝不能影响主流程。
      }
    }
  };

  return {
    scope,
    debug: (message, detail) => log('debug', message, detail),
    info: (message, detail) => log('info', message, detail),
    warn: (message, detail) => log('warn', message, detail),
    error: (message, detail) => log('error', message, detail),
  };
}

// 内置 MCP Server 的 JS 桥：把原生转发的 HTTP 请求交给协议层，再把结果回写原生。
//
// 分层（与 localApiServer 同一套路数）：
//   Kotlin 侧 plugins/mcpServer —— 只做 HTTP 解析 + Bearer 鉴权 + 事件转发，哑管道；
//   本模块 —— 事件契约、协议调用、把 HTTP 结果回写（**顶层不 import react-native**，
//             惰性 require，纯 Node 测试可直接加载）；
//   serverRuntime.js —— 真实能力（读设置、注册工作区工具、跑工具），惰性 require，
//             因为它拖着 AsyncStorage / expo-file-system 这条链，静态引入会毁掉可测性。
//
// 安全边界：本模块**不做**任何档位判断（那是 serverPolicy 的纯函数），也不自己执行工具
// （那是 serverRuntime）——它只负责「协议 → 能力」的接线，接线错了由 serverPolicy 的
// 判决表兜住，判决表错了有单测。

import { createMcpServer, MCP_ENDPOINT_PATH, MCP_SERVER_NAME, MCP_SERVER_VERSION } from './server.js';
import { buildMcpResourceList, buildMcpResourceText } from './serverDocs.js';
import { listExposedTools, normalizeMcpTiers, planToolCall } from './serverPolicy.js';

const EVENT_REQUEST = 'McpServer:onRequest';

// 与 localApiServer 同款：串行队列。同一时刻只处理一个 MCP 请求——工具会动同一个工作区
// 与同一份原生资源（shell/python 看门狗、文件句柄），并发没有收益，只有竞态。
let sharedQueue = Promise.resolve();
function enqueue(task) {
  const run = sharedQueue.then(task, task);
  sharedQueue = run.then(() => {}, () => {});
  return run;
}

let rnState;
function getReactNative() {
  if (rnState !== undefined) return rnState;
  try {
    rnState = require('react-native');
  } catch (error) {
    rnState = null;
  }
  return rnState;
}

function getNative() {
  const rn = getReactNative();
  if (!rn || !rn.Platform || rn.Platform.OS !== 'android') return null;
  const modules = rn.NativeModules || {};
  return modules.McpServer || null;
}

export function isMcpServerAvailable() {
  return Boolean(getNative());
}

function unavailableError() {
  const error = new Error('内置 MCP Server 仅支持 Android（本仓库没有 iOS 原生实现）。');
  error.code = 'MCP_SERVER_UNAVAILABLE';
  return error;
}

// 原生回显的生效 token（空 token 启动时由原生生成）——调用方负责持久化与展示。
export async function startMcpServer({ host, port, token } = {}) {
  const native = getNative();
  if (!native || typeof native.start !== 'function') throw unavailableError();
  const result = await native.start(String(host || ''), Number(port) || 0, String(token || ''));
  return {
    running: result && result.running === true,
    host: String((result && result.host) || host || ''),
    port: Number((result && result.port) || port || 0),
    mcpToken: String((result && result.mcpToken) || token || ''),
  };
}

export async function stopMcpServer() {
  const native = getNative();
  if (!native || typeof native.stop !== 'function') return false;
  await native.stop();
  return true;
}

export async function getMcpServerStatus() {
  const native = getNative();
  if (!native || typeof native.getStatus !== 'function') {
    return { running: false, host: '', port: 0, available: false, lanIp: '' };
  }
  const result = await native.getStatus();
  return {
    running: result && result.running === true,
    host: String((result && result.host) || ''),
    port: Number((result && result.port) || 0),
    available: true,
    lanIp: String((result && result.lanIp) || ''),
  };
}

// 事件契约：原生 emit 一段 JSON 字符串
//   { requestId, method, headers: {…}, body: '<原始请求体字符串>' }
// 数组/对象跨桥不可靠（与 localApiServer 同因），所以统一走 JSON 字符串。
export function parseMcpServerRequest(raw) {
  let parsed = raw;
  if (typeof raw === 'string') {
    try {
      parsed = JSON.parse(raw);
    } catch (error) {
      return null;
    }
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
  const requestId = String(parsed.requestId || '').trim();
  if (!requestId) return null;
  const headers = parsed.headers && typeof parsed.headers === 'object' && !Array.isArray(parsed.headers)
    ? parsed.headers
    : {};
  let body = parsed.body;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      body = null;
    }
  }
  return {
    requestId,
    method: String(parsed.method || 'POST').toUpperCase(),
    path: String(parsed.path || MCP_ENDPOINT_PATH),
    sessionId: String(parsed.sessionId || headers['mcp-session-id'] || headers['Mcp-Session-Id'] || ''),
    headers,
    body,
  };
}

export function addMcpServerRequestListener(callback) {
  const rn = getReactNative();
  if (!rn || !rn.DeviceEventEmitter) return () => {};
  const subscription = rn.DeviceEventEmitter.addListener(EVENT_REQUEST, callback);
  return () => {
    if (subscription && typeof subscription.remove === 'function') subscription.remove();
  };
}

export async function respondMcpServer(requestId, outcome) {
  const native = getNative();
  if (!native || typeof native.respond !== 'function') return false;
  const status = Number((outcome && outcome.status) || 200);
  const headersJson = JSON.stringify((outcome && outcome.headers) || {});
  const body = outcome && outcome.body ? JSON.stringify(outcome.body) : '';
  await native.respond(String(requestId), status, headersJson, body);
  return true;
}

// MCP 的 instructions：握手时读一次。**不写死事实**（档位/工具表都会变），
// 只写「怎么开始」——具体事实让 agent 去读 resources。
// 用函数而不是模块级常量：这里是发给模型看的文案，不是用户可见 UI 文案，
// 但导出常量会被 no-hardcoded-chinese 规则当成「展示给用户的中文」拦下。
export function buildMcpInstructions() {
  return [
    'easychat2 内置 MCP Server：把 App 的工作区工具（文件、搜索、git、shell、扩展包）暴露给外部 agent。',
    '开工前先读 easychat://docs/tools 看当前档位与工具清单，再读 easychat://docs/write-safety 了解写入流程。',
    '默认只有只读档；写入/执行档要用户在 App 的设置里打开。写入与执行类工具第一次调用只会返回预览，',
    '确认无误后带 confirm: true 重发才会真的执行——这不是失败，是设计。',
  ].join('\n');
}

// 组装「协议 + 能力」。能力全部注入，于是这个函数在 Node 里可用假能力直测；
// 生产接线见 serverRuntime.js。
export function createMcpBridge({
  readSettings,
  listDefinitions,
  executeTool,
  workspaceInfo = null,
  serverInfo = { name: MCP_SERVER_NAME, version: MCP_SERVER_VERSION },
  random = Math.random,
  now = () => Date.now(),
  log = () => {},
} = {}) {
  const readTiers = async () => normalizeMcpTiers((await readSettings()).tiers);
  const catalog = () => (typeof listDefinitions === 'function' ? listDefinitions() : []);

  const server = createMcpServer({
    serverInfo,
    instructions: buildMcpInstructions(),
    random,
    now,
    log,
    listTools: async () => {
      const tiers = await readTiers();
      return listExposedTools(catalog(), tiers).map(({ definition, tier }) => ({
        name: definition.name,
        description: String(definition.description || ''),
        inputSchema: definition.parameters && typeof definition.parameters === 'object'
          ? definition.parameters
          : { type: 'object', properties: {} },
        // 档位标注放在 _meta：标准字段之外的自述信息，客户端不认也不会坏。
        _meta: { tier },
      }));
    },
    callTool: async ({ name, args }) => {
      const tiers = await readTiers();
      const definition = catalog().find(item => item.name === name) || null;
      const plan = planToolCall({ name, definition, args, tiers });
      if (plan.kind === 'denied') {
        log('denied', name, plan.tier);
        return { content: plan.message, isError: true, structuredContent: { tool: name, tier: plan.tier, denied: true } };
      }
      if (plan.kind === 'preview') {
        log('preview', name, plan.tier);
        return {
          content: plan.message,
          isError: true,
          structuredContent: { tool: name, tier: plan.tier, preview: true, arguments: plan.args },
        };
      }
      if (typeof executeTool !== 'function') {
        return { content: '服务器未接上工具执行器。', isError: true };
      }
      try {
        const result = await executeTool({
          name,
          args: plan.args,
          tier: plan.tier,
          characterId: String(plan.controls.character_id || ''),
        });
        return { content: (result && result.content) || '', isError: result && result.isError === true };
      } catch (error) {
        return {
          content: `工具执行失败：${(error && error.message) || '未知错误'}`,
          isError: true,
          structuredContent: { tool: name, tier: plan.tier, failed: true },
        };
      }
    },
    listResources: async () => buildMcpResourceList({
      catalog: catalog(),
      tiers: await readTiers(),
    }),
    readResource: async ({ uri }) => {
      const text = buildMcpResourceText({
        uri,
        catalog: catalog(),
        tiers: await readTiers(),
        // 工作区根是异步取的（要读设置）：文档里要写清「当前根在哪」，
        // 否则 agent 只能靠猜路径。取不到就退回「由设置决定」的措辞。
        workspace: typeof workspaceInfo === 'function' ? await workspaceInfo().catch(() => null) : workspaceInfo,
      });
      return text ? { text, mimeType: 'text/markdown' } : null;
    },
  });

  async function handleEvent(event) {
    if (!event) return { status: 400, headers: {}, body: null };
    if (event.path && event.path !== MCP_ENDPOINT_PATH) {
      return { status: 404, headers: {}, body: null };
    }
    return server.handle({
      method: event.method,
      sessionId: event.sessionId,
      headers: event.headers,
      body: event.body,
    });
  }

  return { server, handleEvent, sessions: server.sessions };
}

// 把桥接到原生事件上（生产接线；测试注入假 listen/respond）。
export function attachMcpServer({ bridge, addListener, respond } = {}) {
  const listen = typeof addListener === 'function' ? addListener : addMcpServerRequestListener;
  const reply = typeof respond === 'function' ? respond : respondMcpServer;
  return listen(raw => {
    const event = parseMcpServerRequest(raw);
    if (!event) return sharedQueue;
    return enqueue(async () => {
      let outcome;
      try {
        outcome = await bridge.handleEvent(event);
      } catch (error) {
        outcome = {
          status: 500,
          headers: {},
          body: { jsonrpc: '2.0', id: null, error: { code: -32603, message: (error && error.message) || '内部错误' } },
        };
      }
      try {
        await reply(event.requestId, outcome);
      } catch (error) {}
    });
  });
}

// 对外地址：仅本机 → 回环；局域网 → 原生枚举到的 IPv4（拿不到就留占位符，
// 让用户自己填，而不是编一个可能错的地址给他）。
export function buildMcpServerUrl({ scope = 'loopback', port = 0, lanIp = '' } = {}) {
  const suffix = `${MCP_ENDPOINT_PATH}`;
  if (scope === 'lan') {
    const ip = String(lanIp || '').trim();
    return ip && ip !== '0.0.0.0'
      ? `http://${ip}:${port}${suffix}`
      : `http://<本机局域网 IP>:${port}${suffix}`;
  }
  return `http://127.0.0.1:${port}${suffix}`;
}

// 「复制完整连接配置」的文本（照 Tavo 那份格式）：agent 侧粘一次就能连上。
export function buildMcpConnectionText({ url, token, version = MCP_SERVER_VERSION } = {}) {
  return [
    `easychat2 MCP Server: ${version}`,
    'Preferred access: direct HTTP JSON-RPC',
    `Server URL: ${url}`,
    `Authorization: Bearer ${token || ''}`,
  ].join('\n');
}

export { EVENT_REQUEST as MCP_SERVER_EVENT_REQUEST, MCP_ENDPOINT_PATH };

// 内置 MCP Server 的 `resources/*` 文档（纯函数，Node 可直测）。
//
// 为什么把文档做成资源而不是塞进 initialize 的 instructions：instructions 只在握手时读一次，
// 而档位、工具表、工作区根都会变；agent 需要「随时能再读一遍当前事实」。URI 形态照 Tavo 的
// `tavo://docs/*` 来（agent 侧心智一致），内容全部由**活的能力**生成——工具清单直接从注册表
// 派生，档位状态直接从当前设置派生，不手抄一份会漂移的副本。

import { MCP_ACCESS_TIERS, normalizeMcpTiers, tierNeedsConfirm } from './serverPolicy.js';

export const MCP_RESOURCE_PREFIX = 'easychat://';

export const MCP_DOC_URIS = Object.freeze({
  TOOLS: `${MCP_RESOURCE_PREFIX}docs/tools`,
  WRITE_SAFETY: `${MCP_RESOURCE_PREFIX}docs/write-safety`,
  ACCESS: `${MCP_RESOURCE_PREFIX}docs/access`,
  WORKSPACE: `${MCP_RESOURCE_PREFIX}docs/workspace`,
});

const TIER_TITLE = { read: '只读', write: '写入', exec: '执行' };
const TIER_SUMMARY = {
  read: '读文件、搜索、看 git 状态/日志、读公告板。不产生副作用。',
  write: '建目录/写文件/精确替换、物化仓库、导出 docx 与扩展包、git 提交与回滚、写计划、发公告板消息。',
  exec: '跑命令、跑 Python、触发云构建、安装扩展包，以及 run_subagent / run_team / run_workflow（它们会把工具表交给模型自己挑，等于把执行权转交出去）。',
};

function tierLine(tier, tiers) {
  const on = normalizeMcpTiers(tiers)[tier] === true;
  const need = tierNeedsConfirm(tier) ? '，且必须先看预览再带 confirm: true 重发' : '';
  return `- ${tier}（${TIER_TITLE[tier]}）：${on ? '已开启' : '未开启'}${on ? need : ''}。${TIER_SUMMARY[tier]}`;
}

function groupByTier(catalog) {
  const groups = { read: [], write: [], exec: [] };
  for (const item of Array.isArray(catalog) ? catalog : []) {
    if (groups[item.tier]) groups[item.tier].push(item);
  }
  return groups;
}

function firstLine(text) {
  return String(text || '').split('\n')[0].trim();
}

export function buildMcpResourceList({ catalog = [], tiers } = {}) {
  const resolved = normalizeMcpTiers(tiers);
  const groups = groupByTier(catalog);
  const count = tier => groups[tier].length;
  return [
    {
      uri: MCP_DOC_URIS.TOOLS,
      name: '工具清单与调用约定',
      description: `当前可调用的工具（只读 ${count('read')} / 写入 ${count('write')} / 执行 ${count('exec')}，按档位过滤）。`,
      mimeType: 'text/markdown',
    },
    {
      uri: MCP_DOC_URIS.WRITE_SAFETY,
      name: '写入安全与预览流程',
      description: `写入与执行档的调用流程、被拒绝时的表现、超时语义。当前写入档${resolved.write ? '已开启' : '未开启'}。`,
      mimeType: 'text/markdown',
    },
    {
      uri: MCP_DOC_URIS.ACCESS,
      name: '访问档位说明',
      description: '三个档位各自意味着什么、默认值、以及用户在哪里改。',
      mimeType: 'text/markdown',
    },
    {
      uri: MCP_DOC_URIS.WORKSPACE,
      name: '工作区沙盒说明',
      description: '工具作用的目录在哪、角色沙盒怎么选、character_id 控制字段怎么用。',
      mimeType: 'text/markdown',
    },
  ];
}

export function buildMcpResourceText({ uri, catalog = [], tiers, workspace = null } = {}) {
  const resolved = normalizeMcpTiers(tiers);
  const groups = groupByTier(catalog);
  const target = String(uri || '');

  if (target === MCP_DOC_URIS.TOOLS) {
    const lines = [
      '# easychat2 内置 MCP Server — 工具清单',
      '',
      '## 当前档位',
      ...MCP_ACCESS_TIERS.map(tier => tierLine(tier, resolved)),
      '',
      '## 调用约定',
      '- tools/call 的参数放 `arguments`；返回 `content[].text` 是纯文本结果，`isError: true` 表示这次调用没成功（**不代表服务器不支持**）。',
      '- 控制字段（会被剥离，不会传给工具本身）：',
      '  - `confirm: true` —— 写入/执行档的工具必须带它才真的执行；不带只返回预览。',
      '  - `preview: true` —— 显式只要预览。',
      '  - `character_id` —— 指定操作哪个角色的工作区沙盒（见 easychat://docs/workspace）。',
      '- 写入/执行档的工具**第一次调用只会得到预览**，这是设计如此，不是失败。',
      '',
      '## 工具',
    ];
    for (const tier of MCP_ACCESS_TIERS) {
      const items = groups[tier];
      lines.push('', `### ${tier}（${TIER_TITLE[tier]}）— ${items.length} 个`);
      if (items.length === 0) {
        lines.push('- （当前无可用工具）');
        continue;
      }
      for (const item of items) {
        lines.push(`- \`${item.name}\`：${firstLine(item.description) || '（无描述）'}`);
      }
    }
    return lines.join('\n');
  }

  if (target === MCP_DOC_URIS.WRITE_SAFETY) {
    return [
      '# 写入安全与预览流程',
      '',
      '本服务器的写入/执行类工具**默认关闭**，且即使开启也必须先预览后执行：',
      '',
      '1. 直接调用（不带 confirm）→ 返回 `isError: true` 的预览文本，写明工具名、档位与完整参数，**没有任何副作用**。',
      '2. 判断无误后，带 `confirm: true` 重发同一调用 → 真正执行。',
      '3. 用户也可以直接关闭档位；那时调用会返回「该工具属于 X 档，当前未开启」，不要重试，改请用户去设置里开。',
      '',
      '为什么是 isError: true：这次调用**确实没有执行**，按成功上报会让上层以为已经改了东西。',
      '',
      '## 其它仍然生效的闸门',
      '- 工作区钩子（`.easychat/hooks.json`）的 `before_tool` deny 规则对任意工具生效，命中即拒绝，且**连预览都不会给**。',
      '- 执行类工具本身有超时（run_shell / run_python 由原生看门狗强杀）。超时的返回是「结果未知」而不是「失败」：操作可能已经生效，**先用只读工具确认实际状态，不要盲目重跑写操作**。',
      '- 工作区根是外部文件夹（SAF）时，部分工具（git 三件套等）本来就不存在——`tools/list` 里看不到即不可用。',
    ].join('\n');
  }

  if (target === MCP_DOC_URIS.ACCESS) {
    return [
      '# 访问档位',
      '',
      ...MCP_ACCESS_TIERS.map(tier => tierLine(tier, resolved)),
      '',
      '默认只开只读。档位由用户在 **设置 → MCP 服务器** 里逐个打开；打开即代表用户对「该类操作可以由外部 agent 发起」给出总授权。',
      '',
      '除此之外还有两道与档位无关的闸门：工作区钩子的 deny 规则（见 easychat://docs/write-safety），以及工具自身的实现边界（例如 shell 开关关着时 run_shell 根本不注册）。',
    ].join('\n');
  }

  if (target === MCP_DOC_URIS.WORKSPACE) {
    const lines = [
      '# 工作区沙盒',
      '',
      '所有文件类工具都作用在 App 的**工作区沙盒**里，不是设备任意路径：',
    ];
    if (workspace && workspace.root) {
      lines.push(`- 当前根：${workspace.root}`);
      lines.push(`- 根类型：${workspace.kind === 'saf' ? '用户选择的外部文件夹（SAF）' : '应用私有目录'}`);
    } else {
      lines.push('- 根位置由 App 的工作区设置决定（应用私有目录或用户选择的外部文件夹）。');
    }
    lines.push(
      '- 路径一律写**相对路径**（例如 `notes/a.md`），不要写绝对路径。',
      '- 单聊/角色维度还有一层沙盒：`<root>/<characterId>/`。默认用工作助手（App 内置助手）的沙盒；',
      '  要操作某个角色自己的沙盒，在 arguments 里带 `character_id`（角色 id 可从 App 的角色页查看）。',
      '- 写文件前先 `list_workspace_files` / `read_workspace_file` 确认现状；覆盖是直接覆盖，没有回收站。'
    );
    return lines.join('\n');
  }

  return null;
}

// 本地诊断日志：捕获异常并脱敏留存，供用户/开发者在应用内查看与复制。
//
// 设计约束（与 SECURITY.md「未接入任何分析、广告或遥测 SDK」一致）：
// - 只写本机、绝不上报：不接入 Sentry/Crashlytics 等第三方 SDK，也不发起任何网络请求；
// - 全部文本经 maskSecrets 脱敏，绝不落明文密钥；
// - 有界：内存与持久化都限制条数，避免日志无限增长；
// - 容错：诊断自身失败时静默，绝不影响主流程。
//
// 说明：本模块顶层不放 import，依赖用惰性 require 获取——storage.js 会把本模块
// 间接带入纯 Node 测试环境，顶层 ESM import 在那种加载路径下会解析失败。

const DIAGNOSTICS_KEY = '@easychat2_diagnostics';
const MAX_ENTRIES = 50;
const MAX_FIELD_CHARS = 2000;
const DEDUP_WINDOW_MS = 3000;

// kind：storage（存储损坏/读写失败）、api（接口失败）、webview（卡片渲染异常）、
// unhandled（未捕获异常）、startup（启动异常）、log（分级日志，见 src/logging/）、
// secrets（密钥保险箱降级/引用还原失败，见 storage/secretStore.js）。
// 注意 'secrets' 必须在这里登记：normalizeKind 对未知 kind 会归到 'unhandled'，
// 那样「密钥降级明文」这条最需要被看见的记录会被埋在未捕获异常里。
const VALID_KINDS = ['storage', 'api', 'webview', 'unhandled', 'startup', 'log', 'secrets'];

let asyncStorage;
let asyncStorageLoaded = false;
function getAsyncStorage() {
  if (!asyncStorageLoaded) {
    asyncStorageLoaded = true;
    try {
      asyncStorage = require('@react-native-async-storage/async-storage').default;
    } catch (error) {
      asyncStorage = null;
    }
  }
  return asyncStorage;
}

let maskSecretsFn;
let maskSecretsLoaded = false;
// 惰性 require。**失败绝不缓存**：置位语句放在 require 成功之后（不是进函数就置位），
// 「脱敏器还没就绪」只是这一次降级，下次调用会重试。
//
// 为什么必须这样：旧实现一进函数就 `maskSecretsLoaded = true`，一次 require 失败
// 就把 maskSecretsFn 永久钉成 null——脱敏器从那一刻起对**全部**诊断失效（粘性失败），
// 一次加载异常被放大成「此后所有诊断日志都不脱敏」。脱敏器加载失败是异常态，
// 缓存它等于把异常态固化成常态。
function getMaskSecrets() {
  if (maskSecretsLoaded) return maskSecretsFn;
  try {
    const mod = require('./secrets.js');
    if (typeof mod.maskSecrets !== 'function') return null;
    maskSecretsFn = mod.maskSecrets;
    maskSecretsLoaded = true;
  } catch (error) {
    return null;
  }
  return maskSecretsFn;
}

// 脱敏不可用时的占位文本：**绝不回落原文**。
// 不导出是刻意的：eslint 的硬编码中文规则查「模块级**导出**常量」，非导出常量不在其内，
// 而该文本只出现在诊断日志里（不是界面文案）。含中文也比落明文密钥好得多。
const MASK_UNAVAILABLE_TEXT = '[脱敏不可用，已省略]';

let cache = null;
let writeQueue = Promise.resolve();
// 读-改-写（读 cache → 追加 → 写回）必须整体串行：recordDiagnostic 可并发调用，
// 若各自基于同一份 current 追加，后写的会覆盖先写的，丢掉日志。
let mutationQueue = Promise.resolve();
let lastSignature = '';
let lastAt = 0;

function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value);
}

function truncate(text) {
  const value = clean(text);
  return value.length > MAX_FIELD_CHARS ? value.slice(0, MAX_FIELD_CHARS) : value;
}

// 脱敏的降级方向必须是 **fail-closed**（先例 src/localModel/adapter.js:278
// 「fail-closed：没钥匙也清」）：脱敏器不可用、抛错、或返回非字符串时，一律
// **省略文本**并留占位符，绝不 `truncate(raw)` 回落原文。
//
// 为什么不能回落原文：本文件的对外承诺是「全部文本经 maskSecrets 脱敏，绝不落明文密钥」
// （见文件头第 5 行）。回落原文会把「脱敏器加载失败」这件异常悄悄转换成
// 「把明文 API Key 写进本地诊断日志」——而且旧实现还会把这个失败粘性缓存下来，
// 一次失败等于此后全部诊断都未脱敏。占位符同时让这条异常在日志里可见。
function mask(text) {
  const raw = clean(text);
  const masker = getMaskSecrets();
  if (typeof masker !== 'function') return truncate(MASK_UNAVAILABLE_TEXT);
  try {
    const masked = masker(raw);
    return truncate(typeof masked === 'string' ? masked : MASK_UNAVAILABLE_TEXT);
  } catch (error) {
    return truncate(MASK_UNAVAILABLE_TEXT);
  }
}

function normalizeKind(kind) {
  const key = clean(kind).trim();
  return VALID_KINDS.includes(key) ? key : 'unhandled';
}

export function normalizeDiagnostic(raw) {
  const source = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
  const at = Number(source.at);
  return {
    at: Number.isFinite(at) && at > 0 ? at : Date.now(),
    kind: normalizeKind(source.kind),
    message: truncate(source.message || ''),
    stack: truncate(source.stack || ''),
    context: truncate(source.context || ''),
  };
}

export function formatDiagnostics(list) {
  const entries = (Array.isArray(list) ? list : []).map(normalizeDiagnostic);
  if (entries.length === 0) return '';
  return entries
    .map(entry => {
      const time = new Date(entry.at).toISOString();
      const lines = [`[${time}] ${entry.kind}: ${entry.message}`];
      if (entry.context) lines.push(`  context: ${entry.context}`);
      if (entry.stack) lines.push(`  ${entry.stack}`);
      return lines.join('\n');
    })
    .join('\n\n');
}

async function readCache() {
  if (cache) return cache;
  const store = getAsyncStorage();
  if (!store) {
    cache = [];
    return cache;
  }
  try {
    const raw = await store.getItem(DIAGNOSTICS_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    cache = (Array.isArray(parsed) ? parsed : []).map(normalizeDiagnostic).slice(-MAX_ENTRIES);
  } catch (error) {
    cache = [];
  }
  return cache;
}

function persist(next) {
  const task = writeQueue.then(async () => {
    const store = getAsyncStorage();
    if (!store) return;
    try {
      await store.setItem(DIAGNOSTICS_KEY, JSON.stringify(next));
    } catch (error) {
      // 诊断持久化失败时静默：它不该影响主流程。
    }
  });
  writeQueue = task.catch(() => {});
  return task;
}

// 记录一条诊断。error 可为 Error 或字符串；context 为可选补充说明。
export function recordDiagnostic(kind, error, context = '') {
  try {
    const message = mask(error && error.message !== undefined ? error.message : error);
    const stack = mask(error && error.stack ? error.stack : '');
    const ctx = mask(context);
    const safeKind = normalizeKind(kind);
    // 同内容短窗口去重：连续同错误不刷屏。
    const signature = `${safeKind}|${message}`;
    const now = Date.now();
    if (signature === lastSignature && now - lastAt < DEDUP_WINDOW_MS) {
      return undefined;
    }
    lastSignature = signature;
    lastAt = now;
    const entry = normalizeDiagnostic({ at: now, kind: safeKind, message, stack, context: ctx });
    const task = mutationQueue.then(async () => {
      const current = await readCache();
      const next = [...current, entry].slice(-MAX_ENTRIES);
      cache = next;
      await persist(next);
      return next;
    });
    mutationQueue = task.catch(() => {});
    return task.catch(() => {});
  } catch (error) {
    return undefined;
  }
}

export async function getDiagnostics() {
  const current = await readCache();
  return [...current];
}

export async function clearDiagnostics() {
  cache = [];
  lastSignature = '';
  lastAt = 0;
  const task = mutationQueue.then(async () => {
    const store = getAsyncStorage();
    if (!store) return;
    try {
      await store.removeItem(DIAGNOSTICS_KEY);
    } catch (error) {}
  });
  mutationQueue = task.catch(() => {});
  return task;
}

// 仅测试用：重置内存缓存与惰性依赖。
export function __resetDiagnosticsForTests() {
  cache = null;
  lastSignature = '';
  lastAt = 0;
  writeQueue = Promise.resolve();
  mutationQueue = Promise.resolve();
  asyncStorage = undefined;
  asyncStorageLoaded = false;
  maskSecretsFn = undefined;
  maskSecretsLoaded = false;
}
